 private final GameTestHelper helper;private final MinecraftServer server;private final PartialReloadService service;private final TagRecipeGameTestState originalState;private final ActiveTagRecipeGeneration originalPhysical;private final int accessId,itemId,recipeId;private TagRecipeGameTestPreparation.PreparedFixtureGeneration a,b;private boolean closed;
