 PartialReloadService service(){return service;}MinecraftServer server(){return server;}
 void installGenerationA(){if(a==null)throw new IllegalStateException("not created");service.installTagRecipeGameTestReadyState(new ResourceSnapshot(java.time.Instant.now(),Map.of()),a.snapshot(),a.changeSet(),a.artifact(),(s,e)->e==a.snapshot());var tx=service.requestTagRecipeCommit(server,"gametest-setup-a");service.processTagRecipeSafePoint(server);if(tx.status()!=TagRecipeTransactionStatus.SUCCESS)throw new AssertionError("setup A failed: "+tx.status());}
